mapper.select:

SELECT task_time as taskTime,
        report_time as reportTime,
        task_id as taskIds,
        task_name as taskName,
        letter_num as letterNum,
        config_num as configNum,
        monitor_num as monitorNum,
        control_num as controlNum
FROM ntc_major_task_report

    
        AND report_time >= #{searchReportStartTime}
    
    
        AND report_time < #{searchReportEndTime}
    
    
        AND task_time >= #{searchTaskStartTime}
    
    
        AND task_time < #{searchTaskEndTime}
    
    
        and task_id in
        
            #{item}
        
    
    
        AND task_name like concat(concat('%',#{taskName}),'%')
    

order by reportTime desc;

SELECT task_time as taskTime,
        report_time as reportTime,
        task_id as taskIds,
        task_name as taskName,
        ip_num as ipNum,
        http_num as httpNum,
        mail_num as mailNum,
        vedio_num as vedioNum,
        agent_num as agentNum
FROM ntc_task_report

    
        AND report_time >= #{searchReportStartTime}
    
    
        AND report_time < #{searchReportEndTime}
    
    
        AND task_time >= #{searchTaskStartTime}
    
    
        AND task_time < #{searchTaskEndTime}
    
    
        and task_id in
        
            #{item}
        
    
    
        AND report_type = #{reportType}
    
    
        AND task_name like concat(concat('%',#{taskName}),'%')
    

order by reportTime desc;
